#[path="/Users/themoretheless/Documents/Sources/rrrah/.dedup-work/omni13-20261021/omnisearch-lite--src--settings.rs"]
mod settings;

fn main(){
 let root=std::env::current_exe().unwrap().parent().unwrap().to_path_buf();let primary=root.join("settings.json");assert!(!primary.exists());std::fs::create_dir(&primary).unwrap();
 let appdata=root.join("owned-appdata");assert!(!appdata.exists());std::env::set_var("APPDATA",&appdata);
 let mut s=settings::AppSettings::default();s.window_width=901;s.save();
 let fallback=appdata.join("omnisearch-lite/settings.json");let saved:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(&fallback).unwrap()).unwrap();assert_eq!(saved["window_width"],901);
 let loaded=settings::AppSettings::load();assert_eq!(loaded.window_width,720);
 let overwritten:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(&fallback).unwrap()).unwrap();assert_eq!(overwritten["window_width"],720);
 std::fs::remove_dir_all(appdata).unwrap();std::fs::remove_dir(primary).unwrap();
 println!("{{\"fallback_saved_width\":901,\"load_ignored_fallback_width\":720,\"fallback_overwritten_with_default\":true,\"fixture\":\"owned primary settings path is directory; no Windows permissions parity claim\"}}");
}
